  (4598, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Bachelor of Commerce","organisation":"Degree College Mirpur","detail":"He studied at Degree College Mirpur and obtained a degree in commerce.","source":{"title":"The News: Mohammad Yasin MP: From driving taxi to British Parliament","url":"https://www.thenews.com.pk/print/244407-Mohammad-Yasin-MP-From-driving-taxi-to-BritishParliament"}},{"phase":"career","start":null,"end":null,"title":"Factory worker","organisation":null,"detail":"He came to Bedford from Kashmir in 1992 and soon worked in a factory.","source":{"title":"Hansard: Passchendaele, 13 July 2017 (maiden speech)","url":"https://hansard.parliament.uk/Commons/2017-07-13/debates/69871535-88DE-4EF8-AE0C-9653C8E1B045/Passchendaele#contribution-B4D4A642-B711-4DA3-8F35-956D07A274B0"}},{"phase":"career","start":null,"end":null,"title":"Taxi driver","organisation":null,"detail":"He later became a taxi driver and continued until his election to Parliament.","source":{"title":"Hansard: Passchendaele, 13 July 2017 (maiden speech)","url":"https://hansard.parliament.uk/Commons/2017-07-13/debates/69871535-88DE-4EF8-AE0C-9653C8E1B045/Passchendaele#contribution-B4D4A642-B711-4DA3-8F35-956D07A274B0"}},{"phase":"politics","start":null,"end":null,"title":"Joined the Labour Party","organisation":"Labour Party","detail":"He became involved in trade unionism while working in a factory and then joined the Labour Party.","source":{"title":"The News: Mohammad Yasin MP: From driving taxi to British Parliament","url":"https://www.thenews.com.pk/print/244407-Mohammad-Yasin-MP-From-driving-taxi-to-BritishParliament"}},{"phase":"politics","start":"2006","end":"2006","title":"Elected councillor for Queens Park ward","organisation":"Bedford Borough Council","detail":"He became a councillor for Queens Park ward in 2006.","source":{"title":"Hansard: Passchendaele, 13 July 2017 (maiden speech)","url":"https://hansard.parliament.uk/Commons/2017-07-13/debates/69871535-88DE