ouse/article/where-are-they-now-james-frith"}},{"phase":"politics","start":"2024","end":"2024","title":"Labour candidate for Bury North, general election","organisation":"Labour Party","detail":"He was elected with 19,625 votes.","source":{"title":"Democracy Club: James Frith","url":"https://whocanivotefor.co.uk/person/4286"}}]$bt$::jsonb::text));

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_undo u USING (member_id) WHERE md5(b.background_timeline::text) = u.cur_md5) <> 25 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-11-01a value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = NULL, background_last_checked = NULL
  FROM bt_undo u WHERE b.member_id = u.member_id AND md5(b.background_timeline::text) = u.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (4511, 4515, 4518, 4521, 4523, 4569, 4571, 4573, 4591, 4592, 4595, 4598, 4602, 4607, 4610, 4616, 4617, 4618, 4621, 4630, 4631, 4632, 4634, 4636, 4637) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 25 %, MPs with a timeline %, entries %', changed, changed_outside, with_timeline, entry_total;
  IF changed <> 25 THEN RAISE EXCEPTION 'expected exactly 25 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 25 changed', changed_outside; END IF;
  IF with_timeline <> 321 THEN RAISE EXCEPTION 'expected 321 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 4492 THEN RAISE EXCEPTION 'expected 4492 entries, got %', entry_total; END IF;
END $$;

COMMIT;
